import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
/** Read-only landing/factory consumer inventory, including code absent from source mirrors. */
public final class StaticCompanionEdges {
 public static void main(String[]a)throws Exception{var rows=new ArrayList<String>();try(var j=new JarFile(a[0])){for(var e:Collections.list(j.entries()))if(e.getName().endsWith(".class")){var c=new ClassNode();new ClassReader(j.getInputStream(e)).accept(c,ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);for(var m:c.methods)for(var i:m.instructions){if(i instanceof MethodInsnNode v&&v.owner.equals("local/lito381/server/BattleCompanion")&&Set.of("moveOneTile","relocate","activate").contains(v.name))rows.add(c.name+"\t"+m.name+m.desc+"\tstatic="+((m.access&Opcodes.ACC_STATIC)!=0)+"\t"+v.name+v.desc);if(i instanceof FieldInsnNode v&&v.getOpcode()==Opcodes.PUTFIELD&&v.owner.equals("local/lito381/server/BattleCompanion")&&Set.of("x","y").contains(v.name))rows.add("WRITER\t"+c.name+"\t"+m.name+m.desc+"\t"+v.name);}}}Collections.sort(rows);Files.write(Path.of(a[1]),rows);for(var r:rows)System.out.println(r);}
}
